    {
      "id": "f10",
      "kind": "procedure",
      "text": "Die Prämienverbilligung wird direkt dem Krankenversicherer ausbezahlt und mit den laufenden Prämienrechnungen verrechnet; eine Barauszahlung ist ausgeschlossen.",
      "value_norm": null,
      "segment_ids": ["s0010", "s0011"],
      "must_keep": true
    }
  ],
  "hard_terms": [
    {
      "term": "EG KVG",
      "explanation": "Einführungsgesetz zum Krankenversicherungsgesetz, das die rechtlichen Grundlagen für die Krankenversicherung in der Schweiz regelt.",
      "segment_ids": ["s0003"]
    },
    {
      "term": "obligatorische Krankenpflegeversicherung",
      "explanation": "Die Grundversicherung, die jede in der Schweiz wohnhafte Person haben muss.",
      "segment_ids": ["s0003"]
    },
    {
      "term": "Prämienverbilligung",
      "explanation": "Eine finanzielle Unterstützung, die die Krankenkassenprämien für Personen mit geringem Einkommen reduziert.",
      "segment_ids": ["s0002", "s0010"]
    },
    {
      "term": "Sozialversicherungsstelle",
      "explanation": "Das Amt in der Gemeinde, das für Sozialversicherungen wie die Prämienverbilligung zuständig ist.",
      "segment_ids": ["s0016", "s0019"]
    },
    {
      "term": "Einsprache",
      "explanation": "Ein schriftlicher Widerspruch gegen eine behördliche Verfügung, den man innerhalb einer Frist einreichen muss.",
      "segment_ids": ["s0014", "s0015"]
    }
  ],
  "omit_candidates": [
    {
      "segment_ids": ["s0014", "s0015"],
      "reason": "Details zum Einspruchsverfahren sind für das Grundverständnis nicht zwingend nötig."
    },
    {
      "segment_ids": ["s0012"],
      "reason": "Meldepflicht bei Änderungen kann in einer vereinfachten Version weggelassen werden, wenn die Hauptfrist bereits genannt ist."
    },
    {
      "segment_ids": ["s0011"],
      "reason": "Hinweis, dass keine Barauszahlung erfolgt, ist redundant zur Erklärung der Zahlungsweise."
    }
  ]
}

